// Command gen regenerates internal/dict/skillvec/registry.go.
//
// It APPENDS canonical skills that have no position yet and never reorders the ones
// that do: a position is permanent, and shifting one silently invalidates every
// vector already stored in the search index — no error is raised anywhere, the feed
// simply starts ranking wrongly. Run it after the dictionary grows (see the
// mine-skill-dictionary skill), then commit the regenerated file.
//
// A skill REMOVED from the dictionary keeps its position too. Reclaiming the slot
// would shift nothing by itself, but it would let a future skill inherit a retired
// one's position, and every vector written before that reuse would read the new
// skill's weight at the old skill's slot.
package main

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"regexp"

	"github.com/strelov1/freehire/internal/dict/skilltag"
)

// target is relative to the package directory, which is where `go generate` runs.
const target = "registry.go"

// entry matches one quoted slug per line in the generated slice literal.
var entry = regexp.MustCompile(`(?m)^\t"([^"]+)",$`)

func main() {
	assigned := readAssigned()
	known := make(map[string]bool, len(assigned))
	for _, s := range assigned {
		known[s] = true
	}

	added := 0
	for _, s := range skilltag.Canonicals() {
		if !known[s] {
			assigned = append(assigned, s)
			known[s] = true
			added++
		}
	}

	var buf bytes.Buffer
	buf.WriteString(header)
	for _, s := range assigned {
		fmt.Fprintf(&buf, "\t%q,\n", s)
	}
	buf.WriteString("}\n")

	src, err := format.Source(buf.Bytes())
	if err != nil {
		fail("format", err)
	}
	if err := os.WriteFile(target, src, 0o644); err != nil {
		fail("write", err)
	}
	fmt.Printf("skillvec: %d positions assigned (%d newly appended)\n", len(assigned), added)
}

// readAssigned parses the positions already assigned, in order. A missing file is
// the first run and yields none.
func readAssigned() []string {
	b, err := os.ReadFile(target)
	if err != nil {
		return nil
	}
	matches := entry.FindAllSubmatch(b, -1)
	out := make([]string, 0, len(matches))
	for _, m := range matches {
		out = append(out, string(m[1]))
	}
	return out
}

func fail(step string, err error) {
	fmt.Fprintf(os.Stderr, "skillvec gen: %s: %v\n", step, err)
	os.Exit(1)
}

const header = `// Code generated by internal/dict/skillvec/gen. DO NOT EDIT BY HAND.
//
// A skill's index in this slice IS its permanent vector position. Entries are only
// ever APPENDED: reordering or removing one invalidates every vector stored in the
// search index, silently — the feed would simply start ranking wrongly. Regenerate
// with ` + "`go generate ./internal/dict/skillvec/`" + ` after the dictionary grows.

package skillvec

var registry = []string{
`
